module adder_pipe_64bit (
    input clk, 
    input rst_n, 
    input i_en, 
    input [63:0] adda, 
    input [63:0] addb, 
    output [64:0] result, 
    output o_en
);
// Internal wires and registers
reg [63:0] adda_reg, addb_reg;
reg [64:0] sum_stage1, sum_stage2, sum_stage3, sum_stage4;
reg [64:0] carry_stage1, carry_stage2, carry_stage3, carry_stage4;
reg o_en_reg;
// Pipeline stage 1
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg <= 64'b0;
        addb_reg <= 64'b0;
        sum_stage1 <= 65'b0;
        carry_stage1 <= 65'b0;
    end else if (i_en) begin
        adda_reg <= adda;
        addb_reg <= addb;
        sum_stage1 <= adda_reg + addb_reg;
        carry_stage1 <= {1'b0, sum_stage1};
    end
end
// Pipeline stage 2
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        sum_stage2 <= 65'b0;
        carry_stage2 <= 65'b0;
    end else begin
        sum_stage2 <= sum_stage1;
        carry_stage2 <= carry_stage1;
    end
end
// Pipeline stage 3
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        sum_stage3 <= 65'b0;
        carry_stage3 <= 65'b0;
    end else begin
        sum_stage3 <= sum_stage2;
        carry_stage3 <= carry_stage2;
    end
end
// Pipeline stage 4
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        sum_stage4 <= 65'b0;
        carry_stage4 <= 65'b0;
    end else begin
        sum_stage4 <= sum_stage3;
        carry_stage4 <= carry_stage3;
    end
end
// Output enable generation
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        o_en_reg <= 1'b0;
    end else begin
        o_en_reg <= i_en;
    end
end
// Assign outputs
assign result = sum_stage4;
assign o_en = o_en_reg;
endmodule
